import 'package:flutter_test/flutter_test.dart';
import 'package:Oxygen_Mart/helper/deep_link_parser.dart';
import 'package:Oxygen_Mart/helper/product_share_helper.dart';

void main() {
  group('ProductShareHelper Tests', () {
    test('buildProductDeepLink matches canonical URL format', () {
      const int productId = 123;
      final String deepLink = ProductShareHelper.buildProductDeepLink(productId);

      expect(deepLink, equals('https://new.oxygenmart.online/product/123'));

      // Verify that DeepLinkParser can parse the URL generated by ProductShareHelper
      final Uri uri = Uri.parse(deepLink);
      expect(DeepLinkParser.parseProductId(uri), equals(productId));
    });

    test('buildProductShareText contains product deep link', () {
      const int productId = 456;
      final String shareText = ProductShareHelper.buildProductShareText(productId);

      expect(shareText, contains('https://new.oxygenmart.online/product/456'));
    });
  });
}
